// maven against maven-artifact 4.0.0-rc-7 (testdata/oracle, generated by scripts/oracle), the
// osv-scalibr vectors, the POM version order specification, and native bracket ranges.
import { describe, expect, it } from 'vitest'
import {
  contains,
  fromNative,
  getScheme,
  normalizeVers,
  type Scheme,
  stringifyVers,
  VersError,
} from '../../src/index.ts'
import { divergenceCount } from '../support/divergences.ts'
import { expectTotalOrder, oracleValidity, SIGN } from '../support/oracle.ts'
import { loadComparisonPairs } from '../support/vectors.ts'

const s = getScheme('maven') as Scheme

/** Asserts that each group holds equal versions and the groups are in strictly ascending order. */
function expectOrder(groups: string[][]): void {
  const ranked = groups.flatMap((g, rank) => g.map((v) => [v, rank] as const))
  for (const [a, i] of ranked) {
    for (const [b, j] of ranked) {
      expect(Math.sign(s.compare(a, b)), `${a} vs ${b}`).toBe(Math.sign(i - j))
    }
  }
}

describe('maven against maven-artifact', () => {
  const valid = oracleValidity('maven')

  it('agrees on validity', () => {
    const wrong = valid
      .filter(([v, ok]) => s.isValid(v) !== ok)
      .map(([v, ok]) => `${v} (maven-artifact: ${ok ? 'valid' : 'invalid'})`)
    expect(wrong).toEqual([])
  })

  it('agrees on every comparison', () => {
    const wrong = loadComparisonPairs('oracle/maven.txt')
      .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
      .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
    expect(wrong).toEqual([])
  })

  it('is a total order', () => {
    const sample = valid.filter(([, ok]) => ok).map(([v]) => v)
    expectTotalOrder(
      s,
      sample.filter((_, i) => i % Math.ceil(sample.length / 400) === 0),
    )
  })
})

describe('osv-scalibr vectors', () => {
  const files = ['osv-scalibr/maven-versions.txt', 'osv-scalibr/maven-versions-generated.txt']
  const loaded = files.map((file) => [file, loadComparisonPairs(file)] as const)

  for (const [file, pairs] of loaded) {
    it(file, () => {
      const wrong = pairs
        .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
        .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
      expect(wrong).toEqual([])
    })
  }

  it('every documented divergence matches a vendored pair', () => {
    const divergent = loaded.flatMap(([, pairs]) => pairs.filter((p) => p.divergence))
    expect(divergent.length).toBe(divergenceCount('osv-scalibr/maven'))
  })
})

describe('validity', () => {
  it.each(['1', '1.0-SNAPSHOT', '2.0.0.RELEASE', 'v1_2+3~x', '-', 'x'.repeat(256)])(
    'accepts %s',
    (v) => expect(s.isValid(v)).toBe(true),
  )

  it.each(['', '1 0', '1.0\t', '1.0é', 'x'.repeat(257)])('rejects %j', (v) =>
    expect(s.isValid(v)).toBe(false),
  )

  it('throws on an invalid version', () => {
    expect(() => s.compare('1.0', '')).toThrow(VersError)
  })
})

describe('POM version order specification', () => {
  it('orders qualifiers, numbers and separators', () => {
    expectOrder([
      ['1-alpha'],
      ['1-alpha-1', '1-alpha1', '1-a1', '1-ALPHA-1'],
      ['1-beta'],
      ['1-beta-2', '1-b2'],
      ['1-milestone'],
      ['1-m1'],
      ['1-rc', '1-cr'],
      ['1-rc1', '1-rc-1', '1-cr1', '1-CR1'],
      ['1-snapshot', '1-SNAPSHOT'],
      ['1', '1.0', '1.0.0', '1-0', '1-ga', '1.final', '1-release', '1.GA'],
      ['1-sp'],
      ['1-sp1'],
      // `a` is the alpha alias only before a number; alone it is an unknown qualifier.
      ['1-a'],
      ['1-bar'],
      ['1-foo', '1.foo'],
      ['1-foo2'],
      ['1-foo10'],
      ['1-1'],
      ['1.1'],
      ['1.10'],
      ['2'],
    ])
  })

  it('reads a qualifier after "." as one after "-"', () => {
    expectOrder([['1.0.RC2', '1.0-RC2'], ['1.0-RC3'], ['1.0.1']])
  })

  it('compares numbers of any length', () => {
    expectOrder([['999999999'], ['1000000000'], ['999999999999999999'], ['1000000000000000000000']])
  })
})

describe('fromNative', () => {
  it.each([
    ['[1.0,2.0)', 'vers:maven/>=1.0|<2.0'],
    ['[1.0,2.0]', 'vers:maven/>=1.0|<=2.0'],
    ['(1.0,2.0)', 'vers:maven/>1.0|<2.0'],
    ['[1.5,)', 'vers:maven/>=1.5'],
    ['(,1.0]', 'vers:maven/<=1.0'],
    ['(,1.0],[1.2,)', 'vers:maven/<=1.0|>=1.2'],
    ['[1.0]', 'vers:maven/1.0'],
    ['(,)', 'vers:maven/*'],
    ['(,1.0),(1.0,)', 'vers:maven/!=1.0'],
    [' [1.0 , 2.0) , [3.0,4.0) ', 'vers:maven/>=1.0|<2.0|>=3.0|<4.0'],
    ['[1.0,2.0)[3.0,)', 'vers:maven/>=1.0|<2.0|>=3.0'],
    ['[1,2],[2,3]', 'vers:maven/>=1|<=3'],
    // Like Maven, a restriction after an unbounded one is not checked for overlap.
    ['[1.0,),[0.5,0.9]', 'vers:maven/>=0.5|<=0.9|>=1.0'],
    // A bare version is a minimum, as in the enforcer plugin's range documentation.
    ['1.0', 'vers:maven/>=1.0'],
    ['1.0-SNAPSHOT', 'vers:maven/>=1.0-SNAPSHOT'],
  ])('%s is %s', (native, vers) => {
    expect(stringifyVers(fromNative('maven', native))).toBe(vers)
  })

  it.each([
    ['', 'INVALID_SYNTAX'],
    ['[1.0', 'INVALID_SYNTAX'],
    ['(1.0)', 'INVALID_SYNTAX'],
    ['[1.0)', 'INVALID_SYNTAX'],
    ['[2.0,1.0]', 'INVALID_SYNTAX'],
    ['(1.0,1.0]', 'INVALID_SYNTAX'],
    ['[1,2,3]', 'INVALID_SYNTAX'],
    ['[1.0,2.0),3.0', 'INVALID_SYNTAX'],
    ['[1.0]]', 'INVALID_SYNTAX'],
    ['[1,3],[2,4]', 'INVALID_SYNTAX'],
    ['[1,2],(,3]', 'INVALID_SYNTAX'],
    ['[]', 'INVALID_VERSION'],
    ['[1.0,2 0)', 'INVALID_VERSION'],
  ])('rejects %j with %s', (native, code) => {
    expect(() => fromNative('maven', native)).toThrow(expect.objectContaining({ code }))
  })
})

describe('containment', () => {
  it.each([
    ['vers:maven/>=1.0|<2.0', '2.0-SNAPSHOT', true],
    ['vers:maven/>=1.0|<2.0', '2.0', false],
    ['vers:maven/>=1.0|<2.0', '2.0-sp1', false],
    ['vers:maven/<1.0', '1.0-rc1', true],
    ['vers:maven/1.0', '1.0.0', true],
    ['vers:maven/1.0', '1-ga', true],
    ['vers:maven/>=1.0', '1.0-sp1', true],
  ] as const)('%s contains %s: %s', (range, version, expected) => {
    expect(contains(range, version)).toBe(expected)
  })

  it('sorts constraints by the Maven order when normalising', () => {
    expect(stringifyVers(normalizeVers('vers:maven/1.0-sp1|1.0|1.0-rc1'))).toBe(
      'vers:maven/1.0-rc1|1.0|1.0-sp1',
    )
  })
})
